/**
 * Requires server env: WEBHOOK_SHARED_SECRET (set in deploy/digitalocean/.env)
 * Client must send header: X-Webhook-Secret: <same value>
 * Also requires N8N_BLOCK_ENV_ACCESS_IN_NODE=false (set in docker-compose) so $env works.
 */
function getHeader(headers, name) {
  const n = name.toLowerCase();
  for (const [k, v] of Object.entries(headers || {})) {
    if (String(k).toLowerCase() === n) return v;
  }
  return undefined;
}

function deny(status, message) {
  return [{ json: { blocked: true, status, message } }];
}

const SHARED = $env.WEBHOOK_SHARED_SECRET;
if (!SHARED || String(SHARED).length < 16) {
  return deny(503, 'Server misconfiguration: WEBHOOK_SHARED_SECRET missing or too short');
}

const item = $input.first().json;
const headers = item.headers || {};
const provided = getHeader(headers, 'x-webhook-secret');

if (!provided || String(provided) !== String(SHARED)) {
  return deny(401, 'Unauthorized');
}

return [
  {
    json: {
      blocked: false,
      body: item.body,
      query: item.query,
    },
  },
];
